def build_fewshot_block(df_examples):
    lines = []
    for _, row in df_examples.iterrows():
        lines.append(f"Tweet: {row['tweet']}\nLabel: {row['label']}\n")
    return "\n".join(lines)

fewshot_block = build_fewshot_block(fewshot_examples)
